    /*
     * Assign a Tenant
     * 
     * @param	parentId	UUID
     * @param	assignment 	Tenant 
     * @return	ConnectivityPlan
     */
    public ConnectivityPlan assignTenant( UUID parentId, Tenant assignment ) {
	    LOGGER.info("assigning Tenant as " + assignment.toString() );

	    ConnectivityPlan parentEntity = repository.findById( parentId ).get();
	    assignment = registry.project( Tenant.class, assignment.getTenantId());

	    // ------------------------------------------
		// assign the Tenant to the parent entity
		// ------------------------------------------ 
	    parentEntity.setTenant( assignment );

	    // ------------------------------------------
    	// save the parent entity
    	// ------------------------------------------ 
	    repository.save(parentEntity);
        
	    return parentEntity;
    }
    

	/*
	 * Unassign the Tenant
	 * 
	 * @param	parentId		UUID
	 * @return	ConnectivityPlan
	 */
	public ConnectivityPlan unAssignTenant( UUID parentId ) {
		ConnectivityPlan parentEntity = repository.findById(parentId).get();

		LOGGER.info("unAssigning Tenant on " + parentEntity.toString() );
		
	    // ------------------------------------------
		// null out the Tenant on the parent entithy
		// ------------------------------------------     
	    parentEntity.setTenant(null);

	    // ------------------------------------------
		// save the parent entity
		// ------------------------------------------ 
	    repository.save(parentEntity);
    
	    return parentEntity;
	}


    /*
     * Add to the SimCards
     * 
     * @param	parentID	UUID
     * @param	addTo		childType
     * @return	ConnectivityPlan
     */
    public ConnectivityPlan addToSimCards( UUID parentId, SimCard addTo ) {
	    LOGGER.info("handling AssignSimCardsToConnectivityPlanEvent - " );
	    
	    ConnectivityPlan parentEntity = repository.findById(parentId).get();
	    SimCard child = registry.project( SimCard.class, addTo.getSimCardId());
	    
	    parentEntity.getSimCards().add( child );

	    // ------------------------------------------
    	// save 
    	// ------------------------------------------ 
	    repository.save(parentEntity);
        
	    return parentEntity;
    }
    

    /*
     * Remove from the SimCards
     * 
     * @param	parentID	UUID
     * @param	removeFrom	childType
     * @return	ConnectivityPlan
     */
	public ConnectivityPlan removeFromSimCards( UUID parentId, SimCard removeFrom ) {
	    LOGGER.info("handling RemoveSimCardsFromConnectivityPlanEvent " );
	
	    ConnectivityPlan parentEntity = repository.findById(parentId).get();
	    SimCard child = registry.project( SimCard.class, removeFrom.getSimCardId());
	    
	    parentEntity.getSimCards().remove( child );
	
	    // ------------------------------------------
		// save
		// ------------------------------------------ 
	    update(parentEntity);
	    
	    return parentEntity;
	}



